('c0000001-0000-0000-0000-000000000001', 'b0000001-0000-0000-0000-000000000001', 1, 'Tren inferior + Glúteo + Core', 'Calentamiento 5-6 min → Fuerza en circuito por parejas 22-24 min → Core en suelo 6-7 min. Duración total: 35 min.'),
('c0000001-0000-0000-0000-000000000002', 'b0000001-0000-0000-0000-000000000001', 2, 'Tren superior + Core', 'Calentamiento 5 min → Fuerza tren superior 22-24 min → Core con fitball 6-7 min. Duración total: 35 min.'),
('c0000001-0000-0000-0000-000000000003', 'b0000001-0000-0000-0000-000000000001', 3, 'Full Body — Bandas + Fitball', 'Calentamiento 5 min → Circuito full body 3 vueltas 22-24 min → Vuelta a la calma 4-5 min. Duración total: 35 min.');
